def transform(grid):
 n=len(grid); m=len(grid[0]); colors=list({v for row in grid for v in row if v}); boxes={}
 for c in colors:
  pts=[(r,j) for r,row in enumerate(grid) for j,v in enumerate(row) if v==c]
  boxes[c]=(min(r for r,j in pts),max(r for r,j in pts),min(j for r,j in pts),max(j for r,j in pts))
 colors.sort(key=lambda c:(boxes[c][1]-boxes[c][0])*(boxes[c][3]-boxes[c][2]),reverse=True)
 out=[[0]*m for _ in range(n)]
 for c in colors:
  r0,r1,c0,c1=boxes[c]; h=r1-r0+1; w=c1-c0+1; s=max(h,w)
  if h==n and w==m: a,b,d,e=0,n,0,m
  else:
   a=(n-s)//2; b=a+s; d=(m-s)//2; e=d+s
  for r in range(a,b):
   for j in range(d,e): out[r][j]=c
 return out
